const root = $input.first().json || {};
const workflow = root.workflow || root.input?.workflow || root.input || {};
const nodes = Array.isArray(workflow.nodes) ? workflow.nodes : [];
const connections = workflow.connections && typeof workflow.connections === 'object' ? workflow.connections : {};
const findings = [];
const add = (severity, code, message, remediation, node = null) => findings.push({severity, code, message, remediation, node});

if (!nodes.length) {
  return [{json:{success:false,component_id:'C6-A',component_version:'v1',error:{code:'NO_WORKFLOW_NODES',message:'workflow.nodes must contain at least one node.'},findings:[],score:0,next_action:'provide_workflow_json'}}];
}

const triggerTypes = ['webhook','formTrigger','scheduleTrigger','manualTrigger','executeWorkflowTrigger','emailReadImap','gmailTrigger','microsoftOutlookTrigger'];
if (!nodes.some(n => triggerTypes.some(t => String(n.type||'').includes(t)))) add('high','NO_TRIGGER','No recognizable trigger node was found.','Confirm how the workflow starts and add the appropriate trigger.');

const genericNames = new Set(['HTTP Request','Code','Set','Edit Fields','If','Switch','Merge']);
for (const n of nodes) if (genericNames.has(String(n.name||''))) add('low','GENERIC_NODE_NAME','A node still has a generic default name.','Rename nodes in plain English for supportability.',n.name);

const sourceNames = new Set(Object.keys(connections));
const targetNames = new Set();
for (const branches of Object.values(connections)) { for (const group of (branches.main || [])) for (const link of (group || [])) if (link?.node) targetNames.add(link.node); }
if (nodes.length > 1) { for (const n of nodes) if (!sourceNames.has(n.name) && !targetNames.has(n.name)) add('high','DISCONNECTED_NODE','Node is not connected to the workflow graph.','Connect it or remove it.',n.name); }

const resilience = nodes.some(n => n.retryOnFail === true || n.onError || /error|retry|failure|manual review/i.test(String(n.name||'')));
if (!resilience) add('medium','NO_RESILIENCE_PATH','No retry, failure, or manual-review control was detected.','Add a controlled error/retry/manual-review path.');

const serialized = JSON.stringify(nodes.map(n => n.parameters || {}));
const secretPatterns = [/Bearer\s+[A-Za-z0-9._\-]{16,}/i,/\bsk-[A-Za-z0-9_\-]{12,}/,/"?(api[_-]?key|client[_-]?secret|password|token)"?\s*:\s*"[^={][^"]{7,}"/i];
if (secretPatterns.some(r => r.test(serialized))) add('critical','POSSIBLE_LITERAL_SECRET','Possible literal credential material was detected in node parameters.','Move secrets into n8n Credentials or environment variables and rotate any exposed value.');

if (!workflow.settings?.executionOrder) add('low','MISSING_EXECUTION_SETTING','settings.executionOrder is not declared.','Save/export the workflow from the target n8n version after validation.');
const severityPenalty = {critical:30,high:18,medium:9,low:3};
const score = Math.max(0, 100 - findings.reduce((s,f)=>s+(severityPenalty[f.severity]||5),0));
const blocking = findings.some(f => ['critical','high'].includes(f.severity));
return [{json:{success:true,component_id:'C6-A',component_version:'v1',workflow_name:workflow.name || null,audit:{score,blocking,findings_count:findings.length,findings},next_action:blocking ? 'repair_blocking_findings' : findings.length ? 'review_non_blocking_findings' : 'workflow_audit_passed',error:null}}];
